 static CatalogAsset Prepare(Material snow){
 var tex=(TextureImporter)AssetImporter.GetAtPath(Source+"Palette.png");Require(tex!=null,"palette missing");tex.filterMode=FilterMode.Point;tex.mipmapEnabled=false;tex.wrapMode=TextureWrapMode.Clamp;tex.textureCompression=TextureImporterCompression.Uncompressed;tex.SaveAndReimport();
 var old=CatalogPreparation.Library().Find(Id);if(old&&old.prefab){CatalogPreparation.RecordMetrics(old);Require(old.triangles==3040,"prepared triangle count "+old.triangles);return old;}
 var mat=new Material(Shader.Find("Universal Render Pipeline/Simple Lit")){name="Fuel station | opaque palette",enableInstancing=true};mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Source+"Palette.png"));mat.SetColor("_BaseColor",Color.white);mat.SetColor("_SpecColor",Color.black);mat.SetFloat("_Smoothness",0);mat.SetFloat("_Cull",2);AssetDatabase.CreateAsset(mat,Source+"FuelPalette.mat");
 var importer=(ModelImporter)AssetImporter.GetAtPath(Source+"FuelStation.fbx");Require(importer!=null,"FBX missing");importer.importCameras=false;importer.importLights=false;importer.importAnimation=false;importer.globalScale=1;importer.isReadable=false;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"FuelPalette"),mat);importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"FuelSnow"),snow);importer.SaveAndReimport();
 var draft=CatalogPreparation.Draft("Snow machinery fuel station",CatalogKind.BuildingAssembly,AssetSource.ImportedModel,null,"User supplied Low_Poly_Snow_Machinery_Fuel_Station.blend; SHA256 F75FD6D630441E46D9DFC7A7C00380787F8716FDBFE328A7BF40E398D3DE5CB9. Preserved source; studio Plane/cameras/lights excluded, embedded text not executed.");draft.id=Id;draft.creationSourcePath="SourceAssets/SnowMachineryFuelStation/Low_Poly_Snow_Machinery_Fuel_Station.blend";
 var a=CatalogPreparation.Prepare(AssetDatabase.LoadAssetAtPath<GameObject>(Source+"FuelStation.fbx"),CatalogKind.BuildingAssembly,"Snow machinery fuel station",1,Vector3.zero,AssetSource.ImportedModel,draft.provenance,draft);var path=AssetDatabase.GetAssetPath(a.prefab);var root=PrefabUtility.LoadPrefabContents(path);
