 a.tags=new[]{"fuel-station","canopy","separate-lenses","removable-snow"};a.minimumScale=1;a.maximumScale=1;a.status=PreparationStatus.NeedsReview;a.visualReviewed=false;a.assumptions="Source metres; pump front corrected to +Z. Body static mesh collision keeps canopy drive-under space open. Separate Luminous lenses are opaque palette surfaces, no added real-time lights. Decorative canopy snow is not ledger volume. No hose/nozzle interaction added; originals retain all separate parts. Depot servicing remains existing menu behavior.";a.reviewNotes="Review driving clearance and A07 costs before Ready approval.";CatalogPreparation.RecordMetrics(a);Require(a.triangles==3040,"triangle mismatch "+a.triangles);EditorUtility.SetDirty(a);return a;
