 public static void PlacePrepared(Scene scene){
 var a=CatalogPreparation.Library().Find(Id);if(!a||!a.prefab)return;
 var existing=All<CatalogPlacement>(scene).SingleOrDefault(p=>p.placementId=="pinefall-fuel-station");if(!existing){var go=(GameObject)PrefabUtility.InstantiatePrefab(a.prefab,scene);go.name="Fuel station | imported snow machinery station";go.transform.SetPositionAndRotation(new Vector3(-110,SnowField.Ground,-85),Quaternion.identity);var p=go.GetComponent<CatalogPlacement>();p.placementId="pinefall-fuel-station";PrefabUtility.RecordPrefabInstancePropertyModifications(p);PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);}
 foreach(var t in All<Transform>(scene).Where(t=>t.name=="Fuel tank").ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);
 }
 static Bounds WorldBounds(GameObject go){var rs=go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}
 static void Preview(GameObject go,string file,Vector3 direction){var p=new PreviewRenderUtility();try{var copy=UnityEngine.Object.Instantiate(go);copy.transform.position=Vector3.zero;p.AddSingleGO(copy);foreach(var t in copy.GetComponentsInChildren<WorldSignLabel>())t.Refresh();var b=WorldBounds(copy);p.camera.orthographic=true;p.camera.orthographicSize=Mathf.Max(b.extents.x,b.extents.y)*1.3f;p.camera.nearClipPlane=.1f;p.camera.farClipPlane=300;p.camera.transform.position=b.center+direction.normalized*80;p.camera.transform.LookAt(b.center);p.camera.backgroundColor=new Color(.3f,.4f,.47f);p.camera.clearFlags=CameraClearFlags.SolidColor;p.ambientColor=Color.gray;p.lights[0].intensity=1.2f;p.lights[0].transform.rotation=p.camera.transform.rotation;p.BeginStaticPreview(new Rect(0,0,1200,800));p.Render(true);var image=p.EndStaticPreview();File.WriteAllBytes(Logs+"/"+file+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{p.Cleanup();}}
 [MenuItem("Snowglow/Asset intake/Import snow machinery fuel station")]
 public static void Install(){
 Require(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var scene=SceneManager.GetActiveScene();Require(scene.path==SceneValidation.ScenePath,"open Pinefall");SceneValidation.Validate(scene);Directory.CreateDirectory(Logs);if(!File.Exists(Logs+"/Pinefall-before.unity"))EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before.unity",true);else if(scene.isDirty)EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-unsaved-before.unity",true);
 var snow=All<SnowField>(scene).Single();var original=snow.seed;var originalJson=JsonUtility.ToJson(original.grid);var poses=All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>GlobalObjectId.GetGlobalObjectIdSlow(p).ToString(),p=>p.transform.localToWorldMatrix.ToString("R"));var meshPaths=snow.GetComponentsInChildren<MeshFilter>().Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh)).Where(p=>!string.IsNullOrEmpty(p)).Distinct().ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p));var a=Prepare(snow.palette.snow);PlacePrepared(scene);Physics.SyncTransforms();
 var revision=UnityEngine.Object.Instantiate(original);int changed=0;for(int i=0;i<revision.grid.blocked.Length;i++){bool blocked=Physics.CheckBox(new Vector3(revision.grid.X(i),SnowField.Ground+.85f,revision.grid.Z(i)),new Vector3(SnowVolumeGrid.Cell*.45f,.65f,SnowVolumeGrid.Cell*.45f),Quaternion.identity,1<<0,QueryTriggerInteraction.Ignore);if(blocked!=revision.grid.blocked[i]){revision.grid.blocked[i]=blocked;changed++;}}
 if(changed>0){AssetDatabase.CreateAsset(revision,AssetDatabase.GenerateUniqueAssetPath(CatalogPreparation.Root+"/SceneData/DisposalFuelSnowObstacles.asset"));snow.seed=revision;EditorUtility.SetDirty(snow);}else UnityEngine.Object.DestroyImmediate(revision);
 AssetDatabase.SaveAssets();SceneValidation.Validate(scene);EditorSceneManager.MarkSceneDirty(scene);Require(EditorSceneManager.SaveScene(scene),"save failed");scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);SceneValidation.Validate(scene);MechanicsChecks.Run();snow=All<SnowField>(scene).Single();var actualMask=snow.seed.grid.blocked;snow.seed.grid.blocked=original.grid.blocked;Require(JsonUtility.ToJson(snow.seed.grid)==originalJson,"snow depth/credit/volume changed");snow.seed.grid.blocked=actualMask;
 foreach(var pair in meshPaths)Require(AssetDatabase.GetAssetDependencyHash(pair.Key)==pair.Value,"original snow mesh changed");foreach(var p in All<CatalogPlacement>(scene).Where(p=>poses.ContainsKey(GlobalObjectId.GetGlobalObjectIdSlow(p).ToString())))Require(poses[GlobalObjectId.GetGlobalObjectIdSlow(p).ToString()]==p.transform.localToWorldMatrix.ToString("R"),"existing placement moved "+p.placementId);
 var station=All<CatalogPlacement>(scene).Single(p=>p.placementId=="pinefall-fuel-station");Require(PrefabUtility.IsPartOfPrefabInstance(station),"disconnected station");Require(!All<Transform>(scene).Any(t=>t.name=="Fuel tank"),"primitive tank remains");Require(!station.GetComponentsInChildren<Light>(true).Any(),"unexpected realtime lights");Require(Vector2.Distance(new Vector2(station.transform.position.x,station.transform.position.z),new Vector2(-95,-90))<25,"station outside depot service zone");var sign=All<CatalogPlacement>(scene).First(p=>p.placementId=="pinefall-sign-10");Require(!WorldBounds(station.gameObject).Intersects(WorldBounds(sign.gameObject)),"station intersects fuel sign");var garage=All<CatalogPlacement>(scene).Single(p=>p.placementId=="pinefall-garage");Require(!WorldBounds(station.gameObject).Intersects(WorldBounds(garage.gameObject)),"station intersects garage");
 Preview(station.gameObject,"Station-front",new Vector3(.5f,.5f,1));Preview(station.gameObject,"Station-rear",new Vector3(-.5f,.4f,-1));
 var context=new GameObject("Depot fuel context");context.transform.position=new Vector3(-100,5,-95);try{foreach(var go in new[]{station.gameObject,garage.gameObject,sign.gameObject}){var copy=UnityEngine.Object.Instantiate(go);copy.transform.SetParent(context.transform,true);}Preview(context,"Depot-context",new Vector3(.5f,.7f,1));}finally{UnityEngine.Object.DestroyImmediate(context);}
 a=CatalogPreparation.Library().Find(Id);File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". Fuel station catalog Needs Review: "+a.triangles+" triangles / "+a.renderers+" renderers, two shared materials. Replaced red primitive tank; station at (-110,5.13,-85), in existing depot service zone. Existing fuel sign and garage clear and unmoved. Source studio ground/cameras/lights excluded. Saved/reopened; scene validation and 19 snow checks passed. "+changed+" obstacle flags updated, with separate seed revision if needed; snow depth/credit/volume and original meshes preserved. Other catalog transforms unchanged; no player-save writes or district rebake. Front/rear/depot renders written. Physical driving/refuelling, Android build and A07 performance untested.");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));
